115	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
116	    @Override
117	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
118	        // Normalize the address up front so every downstream use (the required-field check,
119	        // household-duplicate detection, the shared household id and the stored/returned value)
120	        // works from the same canonical form.
121	        String normalizedAddress = normalizeAddress(ownerFieldsDto.getAddress());
122	        List<String> missingFields = new ArrayList<>();
123	        if (isBlank(ownerFieldsDto.getFirstName())) {
124	            missingFields.add("firstName");
125	        }
126	        if (isBlank(ownerFieldsDto.getLastName())) {
127	            missingFields.add("lastName");
128	        }
129	        // Reject an address that is blank once normalized (e.g. whitespace-only input).
130	        if (isBlank(normalizedAddress)) {
131	            missingFields.add("address");
132	        }
133	        if (isBlank(ownerFieldsDto.getCity())) {
134	            missingFields.add("city");
135	        }
136	        if (isBlank(ownerFieldsDto.getTelephone())) {
137	            missingFields.add("telephone");
138	        }
139	        if (!missingFields.isEmpty()) {
140	            throw new InvalidOwnerFieldsException(missingFields);
141	        }
142	        // Determine the effective registration date up front so every downstream use (the daily
143	        // create-limit, the stored value and anything derived from it such as the membership number's
144	        // year segment) works from the same business-day-adjusted date. The effective date is the
145	        // supplied value when present, otherwise the server's current date; a weekend date is rolled
146	        // forward to the following Monday.
147	        LocalDate effectiveRegistrationDate = ownerFieldsDto.getRegistrationDate() != null
148	            ? ownerFieldsDto.getRegistrationDate()
149	            : LocalDate.now();
150	        effectiveRegistrationDate = toBusinessDay(effectiveRegistrationDate);
151	        // Reject the request once the day's owner-creation limit is reached: when 100 or more owners
152	        // already carry this adjusted business day's registration date, no further owners may be
153	        // created for that day.
154	        int ownersRegisteredToday = countOwnersRegisteredOn(effectiveRegistrationDate);
155	        if (ownersRegisteredToday >= MAX_OWNERS_PER_DAY) {
156	            throw new DailyOwnerLimitExceededException(effectiveRegistrationDate);
157	        }
158	        // Flag a bulk signup once more than 80 owners have already been created for this
159	        // business day, sharing the same daily accumulation path as the create-limit rule above.
160	        boolean bulkSignupWarning = ownersRegisteredToday > BULK_SIGNUP_WARNING_THRESHOLD;
161	        // Reject the request when the owner's city is already full: a city that already holds the
162	        // maximum of 50 owners (compared case-insensitively, as elsewhere) accepts no more.
163	        if (countOwnersInCity(ownerFieldsDto.getCity()) >= MAX_OWNERS_PER_CITY) {
164	            throw new CityAtCapacityException(ownerFieldsDto.getCity());
165	        }
166	        // Normalize the telephone into E.164 form; a number that cannot form a valid
167	        // E.164 value is rejected with a 400.
168	        String normalizedTelephone = toE164(ownerFieldsDto.getTelephone());
169	        // Email is optional; when present it must be a syntactically valid address and is
170	        // stored lower-cased. An invalid address is rejected with a 400.
171	        String normalizedEmail = normalizeEmail(ownerFieldsDto.getEmail());
172	        // Derive the household id up front (a deterministic function of the normalized last name and
173	        // address) whenever the caller opts into a shared household, so it can feed the identity key
174	        // below. Owners not admitted into a household have a null household id.
175	        String normalizedLastName = collapse(ownerFieldsDto.getLastName());
176	        String householdId = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())
177	            ? householdId(normalizedLastName, normalizedAddress)
178	            : null;
179	        // All duplicate detection is consolidated into a single derived identity key:
180	        // 'normalizedTelephone + | + (email or empty) + | + householdId'. Because the telephone is
181	        // part of the key, two members of the same household (same householdId) with different
182	        // telephones have different keys and are both allowed; only an exact whole-key match is a
183	        // duplicate. Reject with 409 when a new owner's whole identity key equals an existing one's.
184	        String identityKey = identityKey(normalizedTelephone, normalizedEmail, householdId);
185	        boolean identityInUse = this.clinicService.findAllOwners().stream()
186	            .anyMatch(existing -> identityKey.equals(
187	                identityKey(existing.getTelephone(), existing.getEmail(), existing.getHouseholdId())));
188	        if (identityInUse) {
189	            throw new DuplicateOwnerIdentityException(identityKey);
190	        }
191	        // For a shared household, backfill the shared identifier onto any existing member of this
192	        // household so the whole household carries the same stable value.
193	        if (householdId != null) {
194	            for (Owner existing : this.clinicService.findAllOwners()) {
195	                if (collapse(existing.getLastName()).equals(normalizedLastName)
196	                    && normalizeAddress(existing.getAddress()).equals(normalizedAddress)
197	                    && !householdId.equals(existing.getHouseholdId())) {
198	                    existing.setHouseholdId(householdId);
199	                    this.clinicService.saveOwner(existing);
200	                }
201	            }
202	        }
203	        HttpHeaders headers = new HttpHeaders();
204	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
205	        owner.setAddress(normalizedAddress);
206	        owner.setTelephone(normalizedTelephone);
207	        owner.setEmail(normalizedEmail);
208	        owner.setHouseholdId(householdId);
209	        // Record how many existing owners (before this create) share this owner's first and last
210	        // name, compared case-insensitively. Computed against the current owners so the new owner
211	        // itself is never counted.
212	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
213	        // Record the size of this owner's household (owners sharing the same householdId) after this
214	        // create: the existing members already stamped with the shared identifier plus this new
215	        // owner. An owner not admitted into any household is a household of one.
216	        owner.setHouseholdSize(countHouseholdMembers(householdId) + 1);
217	        // Persist the bulk-signup flag computed above so it is returned on subsequent reads.
218	        owner.setBulkSignupWarning(bulkSignupWarning);
219	        // Store the business-day-adjusted effective registration date computed above. This defaults
220	        // to the server's current date when none was supplied and rolls any weekend date forward to
221	        // the following Monday, so everything derived from it (e.g. the membership number's year
222	        // segment) uses the adjusted date.
223	        owner.setRegistrationDate(effectiveRegistrationDate);
224	        // Assign the customer code: '<CITY3>-<LAST3>-<NNNN>' where CITY3 is the upper-cased first
225	        // three letters of the city, LAST3 the upper-cased first three letters of the last name and
226	        // NNNN is a per-city 4-digit zero-padded sequence equal to one more than the number of
227	        // owners already in that city.
228	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
229	        this.clinicService.saveOwner(owner);
230	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
231	        // Emit an audit trail line for the successful create, carrying the owner id, the assigned
232	        // customer code, the effective registration date and the numeric membership level.
233	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
234	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), ownerDto.getMembershipLevel());
235	        headers.setLocation(UriComponentsBuilder.newInstance()
236	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
237	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
238	    }
