334	    private static boolean isBlank(String value) {
335	        return value == null || value.trim().isEmpty();
336	    }
337	
338	    /**
339	     * Normalize an owner identity field for household-duplicate comparison: trim, collapse every
340	     * run of whitespace to a single space, and lower-case. Used so that last name and address are
341	     * compared case-insensitively with collapsed whitespace.
342	     */
343	    private static String collapse(String value) {
344	        if (value == null) {
345	            return "";
346	        }
347	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
348	    }
349	
350	    /**
351	     * Common street-type abbreviations expanded during address normalization.
352	     */
353	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
354	        "ST", "STREET",
355	        "RD", "ROAD",
356	        "AVE", "AVENUE");
357	
358	    /**
359	     * Normalize an owner address into its canonical stored/compared form: trim, collapse every run
360	     * of whitespace to a single space, upper-case, and expand common street-type abbreviations
361	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). Returns an empty string for
362	     * a {@code null} or blank input. The transformation is idempotent, so an already-normalized
363	     * address maps to itself.
364	     */
365	    private static String normalizeAddress(String value) {
366	        if (value == null) {
367	            return "";
368	        }
369	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase();
370	        if (collapsed.isEmpty()) {
371	            return "";
372	        }
373	        String[] tokens = collapsed.split(" ");
374	        StringBuilder sb = new StringBuilder(collapsed.length());
375	        for (int i = 0; i < tokens.length; i++) {
376	            if (i > 0) {
377	                sb.append(' ');
378	            }
379	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
380	        }
381	        return sb.toString();
382	    }
383	
384	    /**
385	     * Derive the stable household identifier shared by owners with the same normalized last name
386	     * and address. It is a deterministic function of those two values, so every member of a
387	     * household independently derives the same identifier: the first 12 upper-case hex characters
388	     * of {@code SHA-256(normalizedLastName + '\n' + normalizedAddress)}.
389	     */
390	    private static String householdId(String normalizedLastName, String normalizedAddress) {
391	        try {
392	            byte[] digest = MessageDigest.getInstance("SHA-256")
393	                .digest((normalizedLastName + "\n" + normalizedAddress).getBytes(StandardCharsets.UTF_8));
394	            StringBuilder sb = new StringBuilder(digest.length * 2);
395	            for (byte b : digest) {
396	                sb.append(String.format("%02x", b));
397	            }
398	            return sb.substring(0, 12).toUpperCase();
399	        }
400	        catch (NoSuchAlgorithmException e) {
401	            throw new IllegalStateException("SHA-256 not available", e);
402	        }
403	    }
404	
405	    /**
406	     * Derive the identity key into which all duplicate detection is consolidated:
407	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}. A null email or
408	     * household id contributes an empty segment. Two owners are duplicates only when their whole
409	     * identity keys are equal.
410	     */
411	    private static String identityKey(String telephone, String email, String householdId) {
412	        return (telephone == null ? "" : telephone)
413	            + "|" + (email == null ? "" : email)
414	            + "|" + (householdId == null ? "" : householdId);
415	    }
416	
417	    /**
418	     * Build the customer code for a new owner: {@code '<CITY3>-<LAST3>-<NNNN>'} where CITY3 is the
419	     * upper-cased first three letters of the city, LAST3 the upper-cased first three letters of the
420	     * last name and NNNN is a per-city 4-digit zero-padded sequence equal to one more than the
421	     * number of owners already in that city (e.g. {@code 'SYD-SMI-0007'}).
422	     */
423	    /**
424	     * Count the existing owners that share the given first and last name, compared
425	     * case-insensitively. Called before the new owner is saved, so the returned value reflects the
426	     * namesakes that already existed at creation time (the new owner itself is not included).
427	     */
428	    private int countNamesakes(String firstName, String lastName) {
429	        return (int) this.clinicService.findAllOwners().stream()
430	            .filter(existing -> existing.getFirstName() != null && existing.getLastName() != null)
431	            .filter(existing -> existing.getFirstName().equalsIgnoreCase(firstName)
432	                && existing.getLastName().equalsIgnoreCase(lastName))
433	            .count();
434	    }
435	
436	    /**
437	     * Count the existing owners that already belong to the given household (i.e. carry the same
438	     * non-null householdId). Called after any existing members have been backfilled with the shared
439	     * identifier but before the new owner is saved, so the returned value reflects the members that
440	     * already existed at creation time (the new owner itself is not included). Returns 0 when the
441	     * new owner is not part of any household ({@code householdId} is null).
442	     */
443	    private int countHouseholdMembers(String householdId) {
444	        if (householdId == null) {
445	            return 0;
446	        }
447	        return (int) this.clinicService.findAllOwners().stream()
448	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
449	            .count();
450	    }
451	
452	    /**
453	     * The maximum number of owners a single city may contain. Once a city holds this many owners a
454	     * request to create another owner in it is rejected as a conflict.
455	     */
456	    private static final int MAX_OWNERS_PER_CITY = 50;
457	
458	    /**
459	     * Count the existing owners registered in the given city, compared case-insensitively (as in
460	     * {@link #nextCustomerCode}). Called before the new owner is saved, so the returned value
461	     * reflects the owners that already existed at creation time.
462	     */
463	    private int countOwnersInCity(String city) {
464	        return (int) this.clinicService.findAllOwners().stream()
465	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
466	            .count();
467	    }
468	
469	    /**
470	     * The maximum number of owners that may be created on a single day. Once this many owners
471	     * already carry a given day's registration date, a request to create another owner that day is
472	     * rejected with a 429.
473	     */
474	    private static final int MAX_OWNERS_PER_DAY = 100;
475	
476	    /**
477	     * The number of owners that may be created on a single day before the bulk-signup warning is
478	     * flagged. Once more than this many owners already carry a given day's registration date, a
479	     * newly created owner is flagged with {@code bulkSignupWarning} set true.
480	     */
481	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
482	
483	    /**
484	     * Count the existing owners whose registration date is the given day. Called before the new
485	     * owner is saved, so the returned value reflects the owners that already existed at creation
486	     * time.
487	     */
488	    private int countOwnersRegisteredOn(LocalDate date) {
489	        return (int) this.clinicService.findAllOwners().stream()
490	            .filter(existing -> date.equals(existing.getRegistrationDate()))
491	            .count();
492	    }
493	
494	    /**
495	     * Roll a date forward onto a business day: a Saturday or Sunday is advanced to the following
496	     * Monday, while a weekday is returned unchanged. Used so the effective registration date (whether
497	     * supplied or defaulted) always falls on a business day.
498	     */
499	    private static LocalDate toBusinessDay(LocalDate date) {
500	        return switch (date.getDayOfWeek()) {
501	            case SATURDAY -> date.plusDays(2);
502	            case SUNDAY -> date.plusDays(1);
503	            default -> date;
504	        };
505	    }
506	
507	    private String nextCustomerCode(String city, String lastName) {
508	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase();
509	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
510	        long sequence = this.clinicService.findAllOwners().stream()
511	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
512	            .count() + 1L;
513	        return String.format("%s-%s-%04d", city3, last3, sequence);
514	    }
515	
516	    /**
517	     * Required national-number length for each E.164 country calling code we validate: a
518	     * {@code '+61'} (Australia) number carries 9 national digits and a {@code '+1'} (NANP) number
519	     * carries 10. Country codes not listed here are accepted at any (generally valid) length.
520	     */
521	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of(
522	        "1", 10,
523	        "61", 9);
524	
525	    /**
526	     * Convert a raw telephone into E.164 form. Spaces, dashes and brackets are stripped. A leading
527	     * {@code '+'} with its country code is preserved; otherwise the Australian country code
528	     * {@code '+61'} is assumed and a single leading {@code '0'} is dropped from the national digits.
529	     * The result must be a {@code '+'} followed by 8 to 15 digits, and for a recognised country code
530	     * its national-number length must match ({@code '+61'} requires 9 national digits, {@code '+1'}
531	     * requires 10); otherwise an {@link InvalidOwnerFieldsException} is thrown so the request is
532	     * rejected with a 400.
533	     */
534	    private static String toE164(String raw) {
535	        String cleaned = raw.trim().replaceAll("[\\s()\\-]", "");
536	        boolean hasCountryCode = cleaned.startsWith("+");
537	        String digits = hasCountryCode ? cleaned.substring(1) : cleaned;
538	        if (!digits.matches("\\d+")) {
539	            throw new InvalidOwnerFieldsException(List.of("telephone"));
540	        }
541	        if (!hasCountryCode) {
542	            if (digits.startsWith("0")) {
543	                digits = digits.substring(1);
544	            }
545	            digits = "61" + digits;
546	        }
547	        if (digits.length() < 8 || digits.length() > 15) {
548	            throw new InvalidOwnerFieldsException(List.of("telephone"));
549	        }
550	        // For a recognised country code, the national number (the digits after the code) must be
551	        // exactly the expected length for that country. Match the longest known code so a shorter
552	        // code that is a prefix of another cannot mask it.
553	        for (int codeLength = 3; codeLength >= 1; codeLength--) {
554	            if (digits.length() <= codeLength) {
555	                continue;
556	            }
557	            String countryCode = digits.substring(0, codeLength);
558	            Integer requiredNationalLength = NATIONAL_NUMBER_LENGTHS.get(countryCode);
559	            if (requiredNationalLength != null) {
560	                if (digits.length() - codeLength != requiredNationalLength) {
561	                    throw new InvalidOwnerFieldsException(List.of("telephone"));
562	                }
563	                break;
564	            }
565	        }
566	        return "+" + digits;
567	    }
568	
569	    /**
570	     * Pragmatic syntactic check for an email address: a non-empty local part, an {@code @},
571	     * and a domain with at least one dot-separated label, none of which contain whitespace or
572	     * a second {@code @}. This is deliberately permissive but rejects obviously malformed input.
573	     */
574	    private static final Pattern EMAIL_PATTERN =
575	        Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
576	
577	    /**
578	     * Validate and normalize an optional owner email. Returns {@code null} when no email was
579	     * supplied (the field is optional). When supplied it must be a syntactically valid address,
580	     * otherwise an {@link InvalidOwnerFieldsException} is thrown so the request is rejected with a
581	     * 400. A valid address is returned lower-cased.
582	     */
583	    private static String normalizeEmail(String email) {
584	        if (email == null || email.isEmpty()) {
585	            return null;
586	        }
587	        String trimmed = email.trim();
588	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
589	            throw new InvalidOwnerFieldsException(List.of("email"));
590	        }
591	        return trimmed.toLowerCase();
592	    }
593	}
